const SAFE_KEY = /^[A-Za-z0-9][A-Za-z0-9/._-]*$/;

/**
 * Storage keys are generated by the server, but accept only a conservative
 * character set so a malformed key can never escape the storage root or point
 * at an unexpected object.
 */
export function assertSafeStorageKey(key: string): string {
  if (
    !SAFE_KEY.test(key) ||
    key.includes("..") ||
    key.includes("\\") ||
    key.includes("\0")
  ) {
    throw new Error("Invalid storage key");
  }

  return key;
}
